                LHI INPUTPAGE/256D ; HL points to input buffer
__CLSTARTLINE:
                LLI 1D ; point to start of line+1
__CLPREVIOUSCHARACTER:
                DCL ; go back 1
                JTS __CLSTARTLINE ; gone too far, restart.
